package designsystem

// PageLayoutPickerCSS styles the typed layout picker inside the Admin Studio shell.
const PageLayoutPickerCSS = `.ds-layout-picker{grid-column:1/-1;min-width:0;margin:0;padding:0;border:0;display:grid;gap:12px}.ds-layout-picker legend{padding:0;color:var(--ink);font-size:1rem;font-weight:700}.ds-layout-picker__options{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}.ds-layout-option{position:relative;min-width:0;min-height:100px;align-items:flex-start;gap:12px;padding:14px;border:1px solid var(--line);border-radius:var(--radius-md);background:var(--surface);color:var(--ink);cursor:pointer;transition:border-color .16s ease,background-color .16s ease,box-shadow .16s ease}.studio-form .ds-layout-picker__options>.ds-layout-option:last-of-type{grid-column:auto}.ds-layout-option:hover{border-color:var(--brand)}.ds-layout-option:has(input:checked){border-color:var(--brand);background:var(--brand-subtle);box-shadow:0 0 0 1px var(--brand)}.ds-layout-option:focus-within{outline:2px solid var(--brand);outline-offset:2px}.ds-layout-option input{flex:0 0 auto;margin:2px 0 0;accent-color:var(--brand)}.ds-layout-option__preview{flex:0 0 74px;height:58px;display:grid;grid-template-rows:8px 1fr 1fr;gap:4px;padding:7px;border:1px solid var(--line);border-radius:var(--radius-sm);background:var(--bg-subtle)}.ds-layout-option__preview i{display:block;border-radius:3px;background:var(--line-light)}.ds-layout-option__preview i:first-child{width:55%;background:var(--brand)}.ds-layout-option__preview i:nth-child(2){width:100%}.ds-layout-option__preview i:nth-child(3){width:72%}.ds-layout-option__copy{min-width:0;display:grid;gap:4px}.ds-layout-option__copy strong{font-size:.84rem;line-height:1.35}.ds-layout-option__copy small{color:var(--muted);font-size:.74rem;line-height:1.45}@media(max-width:620px){.ds-layout-picker__options{grid-template-columns:1fr}.ds-layout-option{min-height:88px}}`
